package com.college.attendance.controller;

import com.college.attendance.model.AttendanceRecord;
import com.college.attendance.repository.AttendanceRepository;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/attendance")
public class AttendanceController {

    private final AttendanceRepository repo;

    public AttendanceController(AttendanceRepository repo) {
        this.repo = repo;
    }

    @GetMapping("/student/{id}")
    public List<AttendanceRecord> getByStudent(@PathVariable Long id) {
        return repo.findByStudentId(id);
    }

    @PostMapping
    public AttendanceRecord mark(@RequestBody AttendanceRecord record) {
        return repo.save(record);
    }

    @GetMapping("/student/{id}/percentage")
    public double percentage(@PathVariable Long id) {
        List<AttendanceRecord> all = repo.findByStudentId(id);
        long present = repo.findPresentByStudent(id).size();
        return all.isEmpty() ? 0.0 : (present * 100.0) / all.size();
    }
}

